INSERT INTO `admin_settings` (`id`, `setting_name`, `setting_value`, `created_at`, `updated_at`) VALUES
(1, 'onboarding_wp_message', 'Welcome *{name}*! \r\n\r\nCongratulations on enrolling in *{PEPP course}*. \r\nWe\'re excited to have you on board! Your learning journey starts now. Our team will contact you shortly with next steps. \r\n\r\n- `PEPP Learning`', '2025-09-12 09:35:54', '2026-06-13 05:55:25'),
(2, 'user_rejection_wp_message', 'Dear {name}, Thank you for your interest in PEPP Learning. Unfortunately, we cannot proceed with your application at this time. Please feel free to re-apply in the future or contact us for more information.', '2025-09-12 09:35:54', '2026-06-13 05:55:25'),
(3, 'reg_entry_cancelling_message', 'Hi {name}, Your registration for {PEPP course} has been cancelled as requested. If this was done in error or you\'d like to re-register, please contact our support team. Thank you for your interest in PEPP Learning.', '2025-09-12 09:35:54', '2026-06-13 05:55:25'),
(4, 'approval_confirmation_message', 'Congratulations *{name}*! \r\n\r\nWe\'ve approved your joining request to *{PEPP course}* entrance coaching programme for the {academic_year} batch!\r\nHere\'s a quick rundown of what you need to know:\r\n\r\n*Payment Confirmation*:\r\nPaid Amount: *{paid_amount}*\r\nPaid Date: *{joined_date}*\r\nPayment Plan: *{payment_plan}*\r\nPayment Mode: *{payment_mode}*\r\n\r\nTotal Fee: *{total_fee}*\r\nDiscount (if): *{discount_amount}*\r\nTotal Paid: *{collected}*\r\nDue Amount: *{balance}*\r\nDue Date: *{access_end}*\r\n> A gentle reminder (for installment purchases only): To keep your access to the PEPP Learning App and all its valuable features uninterrupted, please settle your balance payment by the due date .\r\n\r\nWe\'re here to support you every step of the way as you prepare for your entrance exam. \r\nLet\'s crack it together!\r\n\r\nBest regards,\r\n`PEPP Learning`', '2025-09-12 09:35:54', '2026-06-13 05:55:25'),
(5, 'approval_app_access_message', '*Here\'s a quick guide to get you started on your learning journey*:\r\n--------------\r\n\r\n1. *Download the PEPP Learning App*:\r\nAndroid: https://play.google.com/store/apps/details?id=com.pepplearning\r\niOS: https://apps.apple.com/in/app/pepp-the-learning-app/id6475805137\r\nWeb Login: https://courses.pepplearning.com/learn/account/signin\r\n\r\n2. *Sign In*\r\nGo to Sign In option\r\nEmail: *{email}*\r\nPassword: *password*\r\n(For your security, we recommend changing your default password)\r\n\r\n3. *Verify Your Mobile Number*\r\nWe\'ll send you a one-time code (OTP) to verify your mobile number. This helps us keep your account secure.\r\n\r\n4. *Access Your Courses*\r\nHead over to the \"Home\" section and confirm you can see your enrolled courses.\r\n--------------\r\n*If you\'ve already downloaded the app, follow these steps*:\r\nHere\'s how to refresh your homepage and view your purchased courses:\r\n\r\na. Tap the menu button. (This is usually three horizontal lines located in the top left corner of your screen.)\r\nb. Select \"Refresh.\" (This might be a specific button or an option within the menu.)\r\nc. Go back to your homepage. (You should now see your paid courses available.)\r\n\r\n\r\nThank you.', '2025-09-12 09:35:54', '2026-06-13 05:55:25'),
(21, 'default_payment_account', '1', '2025-09-12 09:59:20', '2025-09-12 09:59:20'),
(22, 'auto_send_whatsapp', 'yes', '2025-09-12 09:59:20', '2025-09-12 09:59:20'),
(23, 'approval_notification_email', 'admin@peplearning.in', '2025-09-12 09:59:20', '2025-09-12 09:59:20'),
(24, 'instalment_reminder_days', '3', '2025-09-12 09:59:20', '2025-09-12 09:59:20'),
(25, 'overdue_grace_period_days', '7', '2025-09-12 09:59:20', '2025-09-12 09:59:20'),
